import { Mesh, PlaneGeometry, Group, Color, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { textureLoader, emit, fontAtlas } = ctx;

  const root = new Group();

  const geometry = new PlaneGeometry(1.5, 1, 1, 1);
  const material = new MeshBasicNodeMaterial();
  material.color = new Color('#ffffff');

  const plane = new Mesh(geometry, material);
  root.add(plane);

  if (config.imageUrl) {
    textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'center',
    });
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(root.position, {
    y: `+=${0.15}`,
    duration: 0.3,
    ease: 'power3.out',
  });

  const pressTL = gsap.timeline({ paused: true });
  pressTL
    .to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0)
    .to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'power4.out',
    }, '+=0');

  root.userData.handlers = {
    hoverEnter: () => hoverTL.play(),
    hoverLeave: () => hoverTL.reverse(),
    click: () => {
      pressTL.restart();
      emit('hub-journal.select', {});
    },
  };

  root.userData.cleanup = () => {
    hoverTL.kill();
    pressTL.kill();
    if (material.map) material.map.dispose();
    material.dispose();
    geometry.dispose();
  };

  return root;
}
